import{_ as a}from"./chunks/architecture.DdIdPF_l.js";import{_ as i,o,c as t,a5 as s}from"./chunks/framework.BwlBv862.js";const k=JSON.parse('{"title":"Arquitectura de la aplicación y sus servicios","description":"","frontmatter":{"title":"Arquitectura de la aplicación y sus servicios","docId":"developer.architecture","translationKey":"developer.architecture","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"00ea88ebd11714484d717b7d7533d29158afd498121db362a3d300bc21889501","translationRevision":"a001e5ccbafb126c7e19f13427c490f83b2d3f0c0a007959d5ee6f8ad7ca7d5f","order":30},"headers":[],"relativePath":"es/developer/architecture.md","filePath":"es/developer/architecture.md","lastUpdated":1794611623000}'),r={name:"es/developer/architecture.md"};function n(c,e,d,l,p,u){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="application-and-service-architecture" tabindex="-1">Arquitectura de la aplicación y sus servicios <a class="header-anchor" href="#application-and-service-architecture" aria-label="Permalink to &quot;Arquitectura de la aplicación y sus servicios {#application-and-service-architecture}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Coloca cada cambio en el servicio propietario de su estado. Lee <a href="./setup.html">preparación</a> y distingue un host existente de uno independiente iniciado explícitamente. El escritorio construye un solo <code>AppCore</code>, lo envuelve en un <code>ControlApi</code> y expone esa instancia a WebView, CLI local y agentes.</p><h2 id="trace-an-operation" tabindex="-1">Seguir una operación <a class="header-anchor" href="#trace-an-operation" aria-label="Permalink to &quot;Seguir una operación {#trace-an-operation}&quot;">​</a></h2><ol><li>Busca el registro del método en <code>crates/tiktools-control-api/src/modules/</code>. Allí se definen esquemas, políticas y metadatos de descubrimiento.</li><li>Sigue el controlador hacia <code>crates/tiktools-core/src/control/</code> y el servicio propietario. La validación del dominio y las mutaciones persistentes pertenecen aquí, no al adaptador de transporte.</li><li>Añade el método tipado en <code>crates/tiktools-client</code>; la prueba de paridad compara la cobertura del SDK con la superficie registrada.</li><li>Consume el método mediante <code>src/web/shared/api/control-client.ts</code>. Las entidades Vue conservan estado de presentación; el escritorio no entrega a WebView una base de datos ni objetos de integraciones nativas.</li></ol><p>Winit controla el bucle de eventos, Wry la WebView y la integración de bandeja su icono. <code>HostEmitter</code> y los eventos de dominio transportan valores serializados desde el núcleo. El escritorio los entrega mediante su proxy del bucle; la evaluación de scripts permanece en ese hilo. Tokio ejecuta las operaciones asíncronas del host.</p><h2 id="concrete-boundary-check" tabindex="-1">Comprobar un límite concreto <a class="header-anchor" href="#concrete-boundary-check" aria-label="Permalink to &quot;Comprobar un límite concreto {#concrete-boundary-check}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> control-client</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiktools-client</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parity</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span></span></code></pre></div><p>La primera orden verifica el cliente frontend. La segunda ejecuta directamente el destino de integración que compara el SDK y el registro, conservando el archivo de bloqueo. No necesitas abrir una ventana para comprobar estos límites.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Todos los clientes observan la misma operación autoritativa y el mismo recorrido de eventos. <code>host --ipc</code>, <code>host --stdio</code> y <code>--standalone</code> crean deliberadamente un propietario independiente; las órdenes CLI habituales se conectan al existente. <code>PageMessage</code>/<code>IpcRouter</code> permanece como compatibilidad y no debe recibir variantes nuevas.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Si dos clientes discrepan, compara identidad del host, directorio de datos, características compiladas y descubrimiento antes de añadir otro almacén. Un plugin ausente es un problema del catálogo en ejecución, no una razón para compilarlo dentro del núcleo. Los documentos históricos contienen rutas frontend retiradas; ante diferencias, consulta el <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-core/src/lib.rs" target="_blank" rel="noreferrer">núcleo actual</a> y el <a href="./frontend.html">mapa frontend</a>.</p><p><img src="`+a+'" alt="TikTools AppCore, transport, ControlClient e interfaz Vue real"></p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Las features Cargo del binario elegido determinan los recorridos compilados. Los defaults del núcleo activan <code>native-plugins</code> y <code>napi-vm-node-api</code>; <code>persistence</code> aporta SQLite, <code>native-tiktok</code> adaptador/ingreso LIVE, y <code>plugin-install</code>, <code>cloud-auth</code>, <code>app-update</code> sus servicios. Inspecciona <code>cargo tree -p tiktools-desktop -e features</code> (o el CLI elegido), después <code>system.info</code>/discovery. Código compilado no demuestra servicio configurado. Ejercita ingreso LIVE con la regresión <code>native-tiktok</code> de <a href="./performance.html">rendimiento</a>.</p>',16)])])}const b=i(r,[["render",n]]);export{k as __pageData,b as default};
